  f:SetSize(w, h); f:EnableMouse(true)
  f.cw, f.ch, f.u, f.phase = w, h, u, math.random()
  local base = lv(f)
  local function box(fr, b, into)
    fr:SetPoint("TOPLEFT", into or f, "TOPLEFT", b[1] * u, -b[2] * u); fr:SetPoint("BOTTOMRIGHT", into or f, "TOPLEFT", b[3] * u, -b[4] * u)
  end
  -- under everything: the aura, the card body, the empty slot
  f.aura = f:CreateTexture(nil, "BACKGROUND", nil, -8); f.aura:SetTexture(MEDIA .. "Glow"); f.aura:SetBlendMode("ADD")
  f.aura:SetPoint("TOPLEFT", f, "TOPLEFT", -0.24 * w, 0.17 * h); f.aura:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", 0.24 * w, -0.17 * h); f.aura:Hide()
  f.body = f:CreateTexture(nil, "BACKGROUND", nil, 0); f.body:SetTexture(MEDIA .. "Body"); f.body:SetTexCoord(0, 1, 0, CARD_V); f.body:SetAllPoints(f)
  f.slot = f:CreateTexture(nil, "BACKGROUND", nil, 1); f.slot:SetTexture(MEDIA .. "Slot"); f.slot:SetTexCoord(0, 1, 0, CARD_V); f.slot:SetAllPoints(f); f.slot:Hide()
  -- the art window
  f.artClip = CreateFrame("Frame", nil, f); box(f.artClip, U.art); f.artClip:SetFrameLevel(base + 1)
  if f.artClip.SetClipsChildren then f.artClip:SetClipsChildren(true) end
  local aw, ah = (U.art[3] - U.art[1]) * u, (U.art[4] - U.art[2]) * u
  f.aw, f.ah = aw, ah
  f.glow = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 1); f.glow:SetTexture(MEDIA .. "Glow"); f.glow:SetBlendMode("ADD"); f.glow:SetAllPoints(f.artClip)
  -- items: a spotlight in the rarity's colour behind the icon, so the picture is not a small icon on a dark window
  f.spot = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 2); f.spot:SetTexture(MEDIA .. "Glow"); f.spot:SetBlendMode("ADD"); f.spot:Hide()
  f.emb = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 3); f.emb:SetTexture(MEDIA .. "Slots"); f.emb:SetBlendMode("ADD"); f.emb:Hide()
  f.rays = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 2); f.rays:SetTexture(MEDIA .. "Rays"); f.rays:SetBlendMode("ADD")
  f.rays:SetSize(aw * 1.5, aw * 1.5); f.rays:SetPoint("CENTER", f.artClip, "CENTER", 0, 0); f.rays:Hide()
  f.rune = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 3); f.rune:SetTexture(MEDIA .. "Rune"); f.rune:SetBlendMode("ADD")
  f.rune:SetSize(ah * 1.08, ah * 1.08); f.rune:SetPoint("CENTER", f.artClip, "CENTER", 0, 0)
  f.iconBack = f.artClip:CreateTexture(nil, "ARTWORK", nil, 0); f.iconBack:SetColorTexture(0.08, 0.06, 0.1, 0.9)
  f.iconEdge = f.artClip:CreateTexture(nil, "ARTWORK", nil, 1); f.iconEdge:SetColorTexture(GOLDC[1], GOLDC[2], GOLDC[3], 0.95)
  f.art = f.artClip:CreateTexture(nil, "ARTWORK", nil, 2); f.art:SetTexCoord(0.07, 0.93, 0.07, 0.93)
  -- foil sweeps across the whole card, above the model
  f.fx = CreateFrame("Frame", nil, f); f.fx:SetAllPoints(f); f.fx:SetFrameLevel(base + 3)
  if f.fx.SetClipsChildren then f.fx:SetClipsChildren(true) end
  f.foil = f.fx:CreateTexture(nil, "OVERLAY"); f.foil:SetTexture(MEDIA .. "Foil"); f.foil:SetBlendMode("ADD"); f.foil:SetSize(w * 2.2, h * 1.02); f.foil:Hide()
  f.foil:SetPoint("LEFT", f.fx, "LEFT", -w, 0)
  -- frame, text, gem
  f.top = CreateFrame("Frame", nil, f); f.top:SetAllPoints(f); f.top:SetFrameLevel(base + 4)
  f.frameTex = f.top:CreateTexture(nil, "ARTWORK"); f.frameTex:SetTexture(MEDIA .. "Frame"); f.frameTex:SetTexCoord(0, 1, 0, CARD_V); f.frameTex:SetAllPoints(f)
  f.gem = f.top:CreateTexture(nil, "OVERLAY"); f.gem:SetTexture(MEDIA .. "Gem"); f.gem:SetSize(17 * u, 17 * u)
  f.gem:SetPoint("CENTER", f, "TOPLEFT", 229 * u, -214.5 * u)
  f.name = fs(f.top, "head", 15 * u); f.name:SetPoint("TOPLEFT", f, "TOPLEFT", 21 * u, -13 * u); f.name:SetPoint("BOTTOMRIGHT", f, "TOPLEFT", 235 * u, -37 * u)
  f.name:SetJustifyH("CENTER"); f.name:SetJustifyV("MIDDLE"); f.name:SetWordWrap(false); f.name:SetTextColor(0.98, 0.94, 0.82)
  f.type = fs(f.top, "head", 10 * u); f.type:SetPoint("TOPLEFT", f, "TOPLEFT", 20 * u, -206 * u); f.type:SetPoint("BOTTOMRIGHT", f, "TOPLEFT", 210 * u, -223 * u)
  f.type:SetJustifyH("CENTER"); f.type:SetJustifyV("MIDDLE"); f.type:SetWordWrap(false); f.type:SetTextColor(0.85, 0.8, 0.7)
  f.text = fs(f.top, "body", 12 * u); f.text:SetShadowColor(0, 0, 0, 0)
  f.text:SetPoint("TOPLEFT", f, "TOPLEFT", 24 * u, -236 * u); f.text:SetPoint("BOTTOMRIGHT", f, "TOPLEFT", 232 * u, -322 * u)
  f.text:SetJustifyH("LEFT"); f.text:SetJustifyV("TOP"); f.text:SetTextColor(INK[1], INK[2], INK[3])
  f.nameB = fs(f.top, "head", 10.5); f.nameB:SetShadowColor(0, 0, 0, 0); f.nameB:SetTextColor(INK[1], INK[2], INK[3])
  f.nameB:SetJustifyH("CENTER"); f.nameB:SetJustifyV("TOP"); f.nameB:Hide()
  f.pow = fs(f.top, "title", 17 * u); f.pow:SetPoint("CENTER", f, "TOPLEFT", 208 * u, -327 * u); f.pow:SetTextColor(1, 0.92, 0.7)
  f.powLabel = fs(f.top, "head", 6.5 * u); f.powLabel:SetPoint("CENTER", f, "TOPLEFT", 207 * u, -314 * u); f.powLabel:SetTextColor(0.75, 0.7, 0.62); f.powLabel:SetText("POWER")
  f.num = fs(f.top, "head", 8 * u); f.num:SetPoint("LEFT", f, "TOPLEFT", 18 * u, -342 * u); f.num:SetTextColor(0.62, 0.58, 0.78)
  f.fin = fs(f.top, "head", 8 * u); f.fin:SetPoint("RIGHT", f, "TOPLEFT", 158 * u, -342 * u); f.fin:SetTextColor(0.62, 0.58, 0.78); f.fin:SetJustifyH("RIGHT")
  f.count = fs(f.top, "title", 13 * u, "OVERLAY", "OUTLINE"); f.count:SetPoint("TOPRIGHT", f, "TOPLEFT", 235 * u, -49 * u); f.count:SetTextColor(1, 0.95, 0.7)
  f.pin = f.top:CreateTexture(nil, "OVERLAY"); f.pin:SetTexture("Interface\\Cooldown\\star4"); f.pin:SetBlendMode("ADD"); f.pin:SetSize(20 * u, 20 * u)
  f.pin:SetPoint("TOPLEFT", f, "TOPLEFT", 20 * u, -48 * u); f.pin:SetVertexColor(1, 0.85, 0.3); f.pin:Hide()
  f.sparks = {}
  local pos = { { 62, 80 }, { 196, 110 }, { 120, 60 } }
  for i, p in ipairs(pos) do
    local sp = f.top:CreateTexture(nil, "OVERLAY", nil, 3); sp:SetTexture("Interface\\Cooldown\\star4"); sp:SetBlendMode("ADD")
    sp:SetSize((14 + i * 3) * u, (14 + i * 3) * u); sp:SetPoint("CENTER", f, "TOPLEFT", p[1] * u, -p[2] * u); sp:Hide(); f.sparks[i] = sp
  end
  f.hl = f.top:CreateTexture(nil, "OVERLAY", nil, 5); f.hl:SetColorTexture(1, 1, 1, 0); f.hl:SetBlendMode("ADD"); f.hl:SetPoint("TOPLEFT", f, "TOPLEFT", 4 * u, -4 * u); f.hl:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -4 * u, 4 * u)
  f:SetScript("OnMouseUp", function(self, btn) if self.onCard and self.card then self.onCard(self, btn) end end)
  f:SetScript("OnEnter", function(self)
    if self.hover ~= false then self.hl:SetAlpha(0.09) end
    local c = self.card
    if not c or self.noTip then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    if not self.known then GameTooltip:AddLine("Not found yet", 0.6, 0.6, 0.6)
    else
      local t = TIER[c.tier][3]
      GameTooltip:AddLine(c.name, t[1], t[2], t[3])
      GameTooltip:AddLine(KIND[c.kind] .. "  ·  " .. TIER[c.tier][1] .. "  ·  " .. FINISH[self.finish][1], 1, 1, 1)
      GameTooltip:AddLine(c.text, 0.75, 0.75, 0.75, true)
      GameTooltip:AddLine("Power " .. power(c, self.finish), 0.7, 0.9, 0.7)
      if self.copies and self.copies > 1 then GameTooltip:AddLine("You own " .. self.copies, 0.7, 0.7, 0.7) end
    end
    GameTooltip:Show()
  end)
  f:SetScript("OnLeave", function(self) self.hl:SetAlpha(0); GameTooltip:Hide() end)
  return f
end

-- an NPC card shows that creature's own model; a place card a piece of its zone's own world map
local function hasArt(c)
  if c.kind == 2 then return RG.ARCADE_NPC and RG.ARCADE_NPC[c.name] and true or false end
  if c.kind == 3 then return RG.ARCADE_ZONE and RG.ARCADE_ZONE[c.name] and true or false end
  return false
end
local function dressCreature(w, c)
  local id = RG.ARCADE_NPC and RG.ARCADE_NPC[c.name]
  if not id then return false end
  local m = ensureModel(w)
  if not m then return false end
  m.creature = true
  m:ClearAllPoints(); m:SetPoint("TOPLEFT", w.artClip, "TOPLEFT", 2, -2); m:SetPoint("BOTTOMRIGHT", w.artClip, "BOTTOMRIGHT", -2, 2)
  m:SetFrameLevel(lv(w) + 2)
  if not m.SetDisplayInfo then m:Hide() return false end
  local ok = pcall(m.SetDisplayInfo, m, id)
  if not ok then m:Hide() return false end
  if m.SetPortraitZoom then pcall(m.SetPortraitZoom, m, 0.75) end
  if m.SetFacing then pcall(m.SetFacing, m, 0.5) end
  m:Show()
  return true
end
local function zoneArt(w, c)
  local folder = RG.ARCADE_ZONE and RG.ARCADE_ZONE[c.name]
  if not folder then return false end
  if not rawget(w, "zoneTex") then
    w.zoneTex = w.artClip:CreateTexture(nil, "ARTWORK", nil, 1)
    w.zoneTex:SetPoint("TOPLEFT", w.artClip, "TOPLEFT", 2, -2); w.zoneTex:SetPoint("BOTTOMRIGHT", w.artClip, "BOTTOMRIGHT", -2, 2)
  end
  local rnd = rngOf(seedOf(c.name))
  local tile = 1 + math.floor(rnd() * 12)
  local fw = 0.62 + rnd() * 0.14
  local fh = fw * w.ah / w.aw
  local x0, y0 = rnd() * (1 - fw), rnd() * (1 - fh)
  w.zoneTex:SetTexture("Interface\\WorldMap\\" .. folder .. "\\" .. folder .. tile)
  w.zoneTex:SetTexCoord(x0, x0 + fw, y0, y0 + fh)
  w.zoneTex:SetDesaturated(false); w.zoneTex:SetVertexColor(1, 1, 1, 1)
  w.zoneTex:Show()
  return true
end

local function dressModel(w, c, finish)
  local m = ensureModel(w)
  if not m then return false end
  local dir = RACE_DIR[c.race or ""]
  if not dir then m:Hide() return false end
  local g = c.sex == 3 and "Female" or "Male"
  m.cls = c.class
  m:ClearAllPoints(); m:SetPoint("TOPLEFT", w.artClip, "TOPLEFT", 2, -2); m:SetPoint("BOTTOMRIGHT", w.artClip, "BOTTOMRIGHT", -2, 2)
  m:SetFrameLevel(lv(w) + 2)
  local ok = pcall(m.SetModel, m, "Character\\" .. dir .. "\\" .. g .. "\\" .. dir .. g .. ".m2")
  if not ok then m:Hide() return false end
  m:Show()
  return true
end

-- small cards: the name goes on the parchment in a size you can read (two lines if it needs them),
-- with the effect or tier line beneath it. The tiny name plate on top stays empty.
local function layoutText(w, big, name, text)
  local u = w.u
  w.text:ClearAllPoints()
  if big then
    w.nameB:Hide()
    w.text:SetPoint("TOPLEFT", w, "TOPLEFT", 24 * u, -236 * u); w.text:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 232 * u, -322 * u)
    if w.text.SetMaxLines then w.text:SetMaxLines(0) end
    return
  end
  local bw, bh = 200 * u, 82 * u
  local sz = w.cw >= 110 and 11 or 10
  w.nameB:ClearAllPoints()
  w.nameB:SetPoint("TOPLEFT", w, "TOPLEFT", 24 * u, -239 * u); w.nameB:SetWidth(208 * u)
  w.nameB:SetWordWrap(false); setfont(w.nameB, "head", sz); w.nameB:SetText(name or "")
  local lines = 1
  local wd = w.nameB:GetStringWidth()
  if type(wd) == "number" and wd > bw then
    lines = 2
    while sz > 9 and wd > bw * 1.85 do sz = sz - 0.5; setfont(w.nameB, "head", sz); w.nameB:SetText(name or ""); wd = w.nameB:GetStringWidth() end
    w.nameB:SetWordWrap(true)
    if w.nameB.SetMaxLines then w.nameB:SetMaxLines(2) end
  elseif w.nameB.SetMaxLines then w.nameB:SetMaxLines(1) end
  local nh = lines * (sz + 2)
  w.nameB:SetHeight(nh); w.nameB:Show()
  local tsz = 9
  local room = bh - nh - 2
  local tl = math.floor(room / (tsz + 2))
  setfont(w.text, "body", tsz); w.text:SetJustifyH("CENTER"); w.text:SetJustifyV("TOP")
  if text and text ~= "" and tl >= 1 then
    w.text:SetPoint("TOPLEFT", w, "TOPLEFT", 24 * u, -(239 * u + nh + 2)); w.text:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 188 * u, -322 * u)
    if w.text.SetMaxLines then w.text:SetMaxLines(tl) end
    w.text:SetText(text)
  else w.text:SetText("") end
end

-- card: the card; finish: 1-4 or nil (nothing owned); copies: how many you own
local function paint(w, card, finish, copies)
  w.card, w.known, w.finish, w.copies = card, finish ~= nil, finish or 1, copies
  anim[w] = nil
  local mdl = rawget(w, "model"); if mdl then mdl:Hide() end
  local zt = rawget(w, "zoneTex"); if zt then zt:Hide() end
  w.pin:Hide(); w.foil:Hide(); w.aura:Hide(); w.rays:Hide()
  for _, sp in ipairs(w.sparks) do sp:Hide() end
  if not card then w:Hide() return end
  w:Show()
  local u = w.u
  local a = WaypathDB and WaypathDB.arcade
  local t = TIER[card.tier][3]
  w.num:SetText(string.format("#%04d", card.id or 0))
  w.art:ClearAllPoints(); w.iconBack:ClearAllPoints(); w.iconEdge:ClearAllPoints()
  local function placeIcon(sz)
    w.art:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.art:SetSize(sz * u, sz * u)
    w.iconBack:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.iconBack:SetSize((sz + 7) * u, (sz + 7) * u)
    w.iconEdge:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.iconEdge:SetSize((sz + 3) * u, (sz + 3) * u)
  end
  w.art:SetTexture(iconFor(card))
  local scene = usesScene(card) and not hasArt(card)   -- drawn scenery only where the game has no art for the card
  if scene then
    if not rawget(w, "scn") then w.scn = newScene(w.artClip, w.aw, w.ah) end
    setScene(w.scn, card, not finish)
  elseif rawget(w, "scn") then hideScene(w.scn) end
  if not finish then
    -- an empty slot in the binder: a silhouette and the collector number
    w.body:Hide(); w.frameTex:Hide(); w.slot:Show(); w.gem:Hide(); w.glow:Hide(); w.rune:Hide(); w.iconBack:Hide(); w.iconEdge:Hide(); w.spot:Hide(); w.emb:Hide()
    w.art:Show(); w.art:SetDesaturated(true); w.art:SetVertexColor(0, 0, 0, 0.6); placeIcon(74)
    if scene then w.art:Hide() end
    w.nameB:Hide(); w.name:SetText(""); w.type:SetText(""); w.text:SetText(""); w.pow:SetText(""); w.powLabel:Hide(); w.count:SetText(""); w.fin:SetText("")
    w.num:SetTextColor(0.5, 0.45, 0.6)
    return
  end
  w.body:Show(); w.frameTex:Show(); w.slot:Hide(); w.gem:Show(); w.glow:Show(); w.rune:Show(); w.iconBack:Show(); w.iconEdge:Show(); w.art:Show()
  w.num:SetTextColor(0.62, 0.58, 0.78)
  local fx = FX[finish]
  w.fxset = fx
  local kc = KINDCOL[card.kind] or KINDCOL[1]
  w.glow:SetVertexColor(kc[1], kc[2], kc[3], 0.55)
  if card.kind ~= 4 and not scene then
    w.spot:ClearAllPoints(); w.spot:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.spot:SetSize(w.ah * 1.7, w.ah * 1.7)
    w.spot:SetVertexColor(t[1], t[2], t[3], 0.55 + 0.08 * (card.tier or 1)); w.spot:Show()
  end
  if card.kind == 1 then
    local sl = slotOf(card); local c0, r0 = sl % 4, math.floor(sl / 4)
    w.emb:SetTexCoord(c0 * 0.25, (c0 + 1) * 0.25, r0 * 0.25, r0 * 0.25 + 0.25)
    w.emb:ClearAllPoints(); w.emb:SetPoint("CENTER", w.artClip, "CENTER", 0, 2 * u); w.emb:SetSize(w.ah * 0.98, w.ah * 0.98)
    w.emb:SetVertexColor(t[1], t[2], t[3], 0.34); w.emb:Show()
  else w.emb:Hide(); if card.kind == 4 or scene then w.spot:Hide() end end
  tintTex(w.frameTex, t, finish == 1 and 0.82 or 1)
  tintTex(w.gem, t, 1)
  tintTex(w.rune, t, fx.rune)
  tintTex(w.aura, t, 1)
  w.art:SetDesaturated(false); w.art:SetVertexColor(1, 1, 1, 1)
  local full = finish == 4
  if card.kind == 4 and dressModel(w, card, finish) then w.art:Hide(); w.iconBack:Hide(); w.iconEdge:Hide()
  elseif card.kind == 2 and dressCreature(w, card) then w.art:Hide(); w.iconBack:Hide(); w.iconEdge:Hide()
  elseif card.kind == 3 and zoneArt(w, card) then w.art:Hide(); w.iconBack:Hide(); w.iconEdge:Hide(); w.spot:Hide()
  elseif scene then
    w.iconBack:Hide(); w.iconEdge:Hide()
    w.art:Hide()
  else placeIcon(full and 120 or 94) end
  if fx.rays then tintTex(w.rays, { 1, 0.86, 0.5 }, fx.rays); w.rays:Show() end
  if fx.foil > 0 then w.foil:Show() end
  if fx.aura > 0 then w.aura:Show(); w.aura:SetAlpha(fx.aura) end
  if fx.sparks then for _, sp in ipairs(w.sparks) do sp:Show(); tintTex(sp, { 1, 0.95, 0.8 }, 0.8) end end
  -- text
  local compact = w.cw < 190
  if compact then w.name:SetText("") else fitText(w.name, card.name, 214 * u, 15 * u, 8.5, "head") end
  setfont(w.type, "head", math.max(8, 10 * u))
  w.type:SetText(KIND[card.kind] .. "  ·  " .. TIER[card.tier][1])
  setfont(w.count, "title", math.max(9, 13 * u), "OUTLINE")
  setfont(w.num, "head", math.max(6.5, 8 * u))
  local big = w.cw >= 190
  w.text:SetShown(true)
  layoutText(w, big, card.name, TIER[card.tier][1] .. " · " .. FINISH[finish][1])
  if big then
    setfont(w.text, "body", 12.5 * u)
    w.text:SetText((card.text or "") .. "\n\n|cff6b4a2e" .. FINISH[finish][1] .. " print|r")
    w.text:SetJustifyH("LEFT"); w.text:SetJustifyV("TOP")
  end
  w.pow:SetText(power(card, finish)); setfont(w.pow, "title", math.max(8.5, 17 * u))
  w.powLabel:SetShown(w.cw >= 120)
  setfont(w.powLabel, "head", math.max(5.5, 6.5 * u))
  w.fin:SetText(w.cw >= 120 and FINISH[finish][1]:upper() or "")
  w.num:SetShown(w.cw >= 100)
  w.count:SetText(copies and copies > 1 and ("x" .. copies) or "")
  if a and a.showcase then for _, k in ipairs(a.showcase) do if k == (card.key or card.name) then w.pin:Show() end end end
  if fx.foil > 0 or fx.aura > 0 or fx.spin then anim[w] = cardAnim end
end

-- ---------------------------------------------------------------------------
-- Window
-- ---------------------------------------------------------------------------
local frame, cells, reveal, detail
local COLS, ROWS, CELLW = 6, 3, 104
local GRIDX, GRIDY = 118, 150
local WINW, WINH = 790, 730
local view = { kind = 0, show = 1, sort = 1, page = 1, search = "", mode = "cards", set = nil, showcase = false }
local SHOWS = { "All", "Owned", "Missing", "Extras" }
local SORTS = { "Owned", "Collection", "Rarity", "Name", "Power" }
local FNAME = { "Common", "Rare", "Holo", "Full art" }

local function isPinned(a, c)
  for _, k in ipairs(a.showcase or {}) do if k == (c.key or c.name) then return true end end
  return false
end
local function hasExtra(a, c) local s = a.cards[c.key or c.name]; if not s then return false end; for f = 1, 4 do if (s[f] or 0) >= 2 then return true end end return false end

local function collectionList(a)
  local list, q = {}, (view.search or ""):lower()
  for _, c in ipairs(CARDS) do
    local n = owned(a, c.id)
    local ok = view.kind == 0 or c.kind == view.kind
    if ok and view.show == 2 and n == 0 then ok = false end
    if ok and view.show == 3 and n > 0 then ok = false end
    if ok and view.show == 4 and not hasExtra(a, c) then ok = false end
    if ok and q ~= "" and not (c.name:lower():find(q, 1, true) or (c.text or ""):lower():find(q, 1, true)) then ok = false end
    if ok and view.set and setOf(c) ~= view.set then ok = false end
    if ok and view.showcase and not isPinned(a, c) then ok = false end
    if ok then list[#list + 1] = c end
  end
  if view.sort == 1 then
    local have = {}
    for _, c in ipairs(list) do have[c] = owned(a, c.id) > 0 end
    table.sort(list, function(x, y) if have[x] ~= have[y] then return have[x] end return (x.id or 0) < (y.id or 0) end)
  elseif view.sort == 3 then table.sort(list, function(x, y) if x.tier ~= y.tier then return x.tier > y.tier end return x.name < y.name end)
  elseif view.sort == 4 then table.sort(list, function(x, y) return x.name < y.name end)
  elseif view.sort == 5 then table.sort(list, function(x, y) return power(x, bestFinish(a, x.id) or 1) > power(y, bestFinish(a, y.id) or 1) end) end
  return list
end

local function kit(...)   -- the first SOUNDKIT id this client has
  if not SOUNDKIT then return nil end
  for i = 1, select("#", ...) do local k = select(i, ...); if SOUNDKIT[k] then return SOUNDKIT[k] end end
end
-- our own sound effects (Media/Sounds, synthesised by tools/arcade/sounds.py); the Arena's Sound button silences them too
local SND = "Interface\\AddOns\\Waypath\\Media\\Sounds\\"
local function playFx(name)
  local a = store()
  if a and a.mute then return true end   -- muted counts as handled
  if not PlaySoundFile then return false end
  local ok, willPlay = pcall(PlaySoundFile, SND .. name .. ".ogg", "SFX")
  return ok and willPlay ~= false
end
RG.ArcadeFx = playFx
-- role: "flip" (a card turns), "hover" (a rare card is nearby), "crack" (the seal tears), "pick" (a chip of the seal), "best" (personal best), "deal", "reward", "toast"
local function playSound(finish, tier, role)
  local fx
  if role == "hover" or role == "pick" or role == "best" or role == "deal" or role == "reward" or role == "toast" then fx = role
  elseif role == "crack" then fx = "crack"
  elseif tier == 6 then fx = "flip_legend"
  elseif finish and finish >= 4 then fx = "flip_full"
  elseif finish == 3 then fx = "flip_holo"
  elseif finish == 2 then fx = "flip_rare"
  else fx = "flip_common" end
  if playFx(fx) then return end
  if not (PlaySound and SOUNDKIT) then return end
  local id
  if role == "hover" then id = kit("IG_MAINMENU_OPTION_CHECKBOX_ON", "IG_CHARACTER_INFO_TAB")
  elseif role == "pick" then id = kit("IG_CHARACTER_INFO_TAB", "IG_MAINMENU_OPTION_CHECKBOX_ON")
  elseif role == "crack" then id = kit("IG_MAINMENU_OPEN", "IG_BACKPACK_OPEN", "IG_QUEST_LIST_OPEN")
  elseif role == "best" or role == "reward" or role == "toast" then id = kit("UI_LEGENDARY_LOOT_TOAST", "LEVEL_UP", "UI_EPICLOOT_TOAST")
  elseif tier == 6 then id = kit("UI_LEGENDARY_LOOT_TOAST", "LEVEL_UP")
  elseif finish and finish >= 4 then id = kit("UI_EPICLOOT_TOAST", "UI_LEGENDARY_LOOT_TOAST", "IG_QUEST_LIST_COMPLETE")
  elseif finish == 3 then id = kit("UI_EPICLOOT_TOAST", "IG_QUEST_LIST_COMPLETE")
  elseif finish == 2 then id = kit("IG_QUEST_LIST_OPEN", "IG_ABILITY_PAGE_TURN")
  elseif role == "deal" then id = nil
  else id = kit("IG_ABILITY_PAGE_TURN", "IG_BACKPACK_OPEN") end
  if id then pcall(PlaySound, id) end
end

-- a dark panel with gold trim, used by the pop-ups
local function darkPanel(f, w, h)
  f:SetSize(w, h)
  f:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 2 })
  f:SetBackdropColor(0.04, 0.03, 0.09, 0.98); f:SetBackdropBorderColor(0.72, 0.58, 0.3, 1)
  local night = f:CreateTexture(nil, "BACKGROUND", nil, 1); night:SetTexture(MEDIA .. "Night"); night:SetPoint("TOPLEFT", 2, -2); night:SetPoint("BOTTOMRIGHT", -2, 2); night:SetAlpha(0.9)
  local corners = {}
  for i = 1, 4 do
    local c = f:CreateTexture(nil, "OVERLAY"); c:SetTexture(MEDIA .. "Corner"); c:SetSize(46, 46)
    local right, bottom = (i == 2 or i == 4), (i == 3 or i == 4)
    c:SetPoint((bottom and "BOTTOM" or "TOP") .. (right and "RIGHT" or "LEFT"), right and -3 or 3, bottom and 3 or -3)
    c:SetTexCoord(right and 1 or 0, right and 0 or 1, bottom and 1 or 0, bottom and 0 or 1)
    corners[i] = c
  end
  return night
end

-- a face-down card: click it and the back turns over
local function makeCover(card)
  local c = CreateFrame("Button", nil, card)
  c:SetPoint("CENTER"); c:SetSize(card.cw, card.ch); c:SetFrameLevel(lv(card) + 10)
  c.cw, c.ch, c.phase = card.cw, card.ch, math.random()
  c.glow = c:CreateTexture(nil, "BACKGROUND", nil, -8); c.glow:SetTexture(MEDIA .. "Glow"); c.glow:SetBlendMode("ADD")
  c.glow:SetPoint("TOPLEFT", c, "TOPLEFT", -0.3 * card.cw, 0.22 * card.ch); c.glow:SetPoint("BOTTOMRIGHT", c, "BOTTOMRIGHT", 0.3 * card.cw, -0.22 * card.ch); c.glow:Hide()
  c.tex = c:CreateTexture(nil, "ARTWORK"); c.tex:SetTexture(MEDIA .. "Back"); c.tex:SetTexCoord(0, 1, 0, CARD_V); c.tex:SetAllPoints(c)
  c.shine = c:CreateTexture(nil, "OVERLAY"); c.shine:SetColorTexture(1, 1, 1, 1); c.shine:SetBlendMode("ADD"); c.shine:SetAlpha(0); c.shine:SetPoint("TOPLEFT", 3, -3); c.shine:SetPoint("BOTTOMRIGHT", -3, 3)
  -- hold the mouse on a card to peel its bottom edge up: you see the bottom of the card and a bar in its print's colour
  c.fold = c:CreateTexture(nil, "OVERLAY"); c.fold:SetColorTexture(0, 0, 0, 0.5); c.fold:SetPoint("BOTTOMLEFT", c, "BOTTOMLEFT", 0, 0); c.fold:SetPoint("BOTTOMRIGHT", c, "BOTTOMRIGHT", 0, 0); c.fold:SetHeight(7); c.fold:Hide()
  c.peek = c:CreateTexture(nil, "OVERLAY", nil, 2); c.peek:SetColorTexture(1, 1, 1, 1); c.peek:SetSize(46, 5); c.peek:SetPoint("BOTTOM", c, "BOTTOM", 0, 1); c.peek:Hide()
  c.rare, c.cued, c.peel, c.lift, c.holding = false, false, 0, 0, false
  local function layout(self)
    local ch = card.ch
    local h = ch * (1 - 0.24 * self.peel)
    self:SetHeight(h)
    self:ClearAllPoints(); self:SetPoint("CENTER", 0, (ch - h) / 2 + self.lift)
    self.tex:SetTexCoord(0, 1, 0, CARD_V * (1 - 0.24 * self.peel))
    if self.peel > 0.05 then self.fold:Show() else self.fold:Hide() end
    if self.peel > 0.5 then self.peek:Show() else self.peek:Hide() end
  end
  c.layout = layout
  local function peelTick(self, dt)
    if self.flipping == true then return end
    self.peel = math.min(1, self.peel + dt * 3.5)
    layout(self)
  end
  local function drop(self)
    self.holding, self.peel = false, 0
    if self.flipping ~= true then self:SetScript("OnUpdate", nil); layout(self) end
  end
  c:SetScript("OnEnter", function(self)
    self.shine:SetAlpha(self.rare and 0.18 or 0.1)
    if self.flipping == true then return end
    self.lift = 5; layout(self)
    if self.rare and not self.cued then self.cued = true; playSound(nil, nil, "hover") end   -- a card worth the wait is under your mouse
  end)
  c:SetScript("OnLeave", function(self)
    self.shine:SetAlpha(0); self.lift = 0
    drop(self)
    if self.flipping ~= true then layout(self) end
  end)
  c:SetScript("OnMouseDown", function(self)
    if self.flipping == true then return end
    local col = self.peekCol or { 0.6, 0.6, 0.65 }
    self.peek:SetColorTexture(col[1], col[2], col[3], 1)
    self.holding = true; self:SetScript("OnUpdate", peelTick)
  end)
  c:SetScript("OnMouseUp", function(self) drop(self) end)
  card.cover = c
  return c
end
local function coverAnim(c, t)
  local h = (t * 0.35 + c.phase) % 1
  local r, g, b = 0.6 + 0.4 * math.sin(h * 6.283), 0.6 + 0.4 * math.sin(h * 6.283 + 2.09), 0.6 + 0.4 * math.sin(h * 6.283 + 4.19)
  c.glow:SetVertexColor(r, g, b, 0.55 + 0.25 * math.sin(t * 3 + c.phase * 5))
end

local function oddsText(g)
  if not g.odds then return "" end
  return "   ·   about 1 in " .. groupDigits(g.odds) .. " cards"
end
local function summarize()
  local best, bi
  for i, g in ipairs(reveal.got) do
    local sc = g.finish * 10 + g.card.tier
    if not best or sc > best then best, bi = sc, i end
  end
  local g = reveal.got[bi]
  local meta = reveal.meta or {}
  local lines = {}
  if meta.many then
    local m = meta.many
    lines[#lines + 1] = m.count .. " packs opened   ·   " .. m.total .. " cards   ·   " .. m.new .. " new" .. (m.newPrint > 0 and (", " .. m.newPrint .. " new prints") or "") ..
      "   ·   duplicates worth " .. m.value .. " coins"
    lines[#lines + 1] = "Best of the haul: " .. GOLDHEX .. g.card.name .. "|r  (" .. FNAME[g.finish] .. ")" .. oddsText(g)
  else
    local new = 0
    for _, x in ipairs(reveal.got) do if x.new then new = new + 1 end end
    lines[#lines + 1] = "Best pull: " .. GOLDHEX .. g.card.name .. "|r  (" .. FNAME[g.finish] .. ")" .. oddsText(g) .. "   ·   " .. new .. " new"
  end
  if reveal.record then lines[#lines + 1] = "|cffffd36bYour rarest pull yet!|r" end
  if meta.sets then
    local bits = {}
    for i = 1, math.min(2, #meta.sets) do
      local x = meta.sets[i]
      if x.gained > 0 or i == 1 then bits[#bits + 1] = x.name .. " " .. x.have .. "/" .. x.total .. (x.gained > 0 and (" |cff7be08a(+" .. x.gained .. ")|r") or "") end
    end
    if #bits > 0 then lines[#lines + 1] = "|cffa89bc9Sets:|r " .. table.concat(bits, "   ·   ") end
  end
  if meta.daily and meta.streak then lines[#lines + 1] = "|cffa89bc9Pack streak:|r day " .. meta.streak .. (meta.streak % 7 == 0 and "  (reward pack earned)" or "") end
  if reveal.notes and #reveal.notes > 0 then lines[#lines + 1] = "|cff7be08a" .. table.concat(reveal.notes, "   ·   ") .. "|r" end
  reveal.sum:SetText(table.concat(lines, "\n"))
end

local function burstAt(card, strength)
  reveal.burst:ClearAllPoints(); reveal.burst:SetPoint("CENTER", card, "CENTER", 0, 0)
  local s = card.cw * (2.6 + strength * 0.5)
  reveal.burst:SetSize(s, s)
  local t = card.fxset and TIER[card.card.tier][3] or { 1, 0.85, 0.5 }
  tintTex(reveal.burst, { math.min(1, t[1] + 0.3), math.min(1, t[2] + 0.3), math.min(1, t[3] + 0.3) }, 1)
  reveal.burstLeft, reveal.burstMax = 1.1 + 0.3 * strength, 1.1 + 0.3 * strength
  reveal.burstSpin = 0
  reveal.burst:Show()
end

local function badgeFor(g)
  if g.new then return GOLDHEX .. "NEW|r" end
  if g.newPrint then local t = TIER[g.card.tier][3]; return string.format("|cff%02x%02x%02x", math.floor(t[1] * 255 + 0.5), math.floor(t[2] * 255 + 0.5), math.floor(t[3] * 255 + 0.5)) .. "NEW PRINT|r" end
  return "|cff9a96b0Extra · " .. (g.value or 0) .. "c|r"
end
local function flip(i)
  local card = reveal.cards[i]
  local c = card.cover
  if not c or c.flipping == true or not c:IsShown() or reveal.phase then return end
  c.flipping = true; anim[c] = nil
  c.peel, c.lift, c.holding = 0, 0, false
  c.fold:Hide(); c.peek:Hide(); c:SetHeight(card.ch); c.tex:SetTexCoord(0, 1, 0, CARD_V)
  c:ClearAllPoints(); c:SetPoint("CENTER", 0, 0)
  local g0 = reveal.got[i]
  local weight = g0.card.tier == 6 and 3 or (g0.finish >= 3 and 2 or (g0.finish == 2 and 1 or 0))
  local span = weight >= 2 and 0.6 or (weight == 1 and 0.34 or 0.22)   -- the better the card, the longer the wait
  local t = 0
  c:SetScript("OnUpdate", function(self, dt)
    t = t + dt
    local k = 1 - t / span
    if k > 0.02 then
      self:SetWidth(math.max(1, card.cw * k))
      if weight >= 2 then self:ClearAllPoints(); self:SetPoint("CENTER", math.sin(t * 60) * 2.5 * (1 - k), 0) end   -- it trembles
    else
      self:SetScript("OnUpdate", nil); self:Hide(); self.flipping = false
      local g = reveal.got[i]
      reveal.flipped = reveal.flipped + 1
      card.new:SetText(badgeFor(g))
      local big = weight
      playSound(g.finish, g.card.tier)
      if big > 0 then burstAt(card, big) end
      if big >= 2 then reveal.shakeT, reveal.shakeK = 0.35, big end
      if g.record then reveal.record = true; reveal.title:SetText("Your rarest pull yet!"); playSound(nil, nil, "best") end
      if reveal.flipped >= #reveal.got then
        reveal.all:Hide(); reveal.ok:SetText("Done")
        if not reveal.record then reveal.title:SetText("Pack opened") end
        reveal.share:Show(); summarize()
      end
    end
  end)
end

local function afford()
  local a = store()
  return a and (((a.bonus or 0) > 0) or ((a.free or 0) > 0) or (a.coins or 0) >= PACK_PRICE)
end

local RW, RCARD, RGAP = 790, 140, 8
local function dealPositions(i)
  local total = PACK_SIZE * RCARD + (PACK_SIZE - 1) * RGAP
  return (RW - total) / 2 + (i - 1) * (RCARD + RGAP), -64
end

local function startDeal()
  reveal.phase = "deal"; reveal.dealT = 0
  reveal.sealFade = 0.55; reveal.sealGlow:Hide()
  reveal.title:SetText("Turn each card")
  for i = 1, PACK_SIZE do reveal.cards[i]:Show(); reveal.cards[i]:SetAlpha(0) end
  reveal.sum:SetText("|cff9a96b0Hold a card to peek at how rare it is, let go to turn it|r")
  playSound(nil, nil, "deal")
end

local function cursorXY()
  if not GetCursorPosition then return 0, 0 end
  local x, y = GetCursorPosition()
  local sc = UIParent and UIParent.GetEffectiveScale and UIParent:GetEffectiveScale() or 1
  if type(x) ~= "number" or type(y) ~= "number" or type(sc) ~= "number" or sc == 0 then return 0, 0 end
  return x / sc, y / sc
end
-- the seal gives way: shards fly, the table jolts, the cards are dealt
local function tearOpen()
  if reveal.phase ~= "seal" then return end
  playSound(nil, nil, "crack"); if playFx then playFx("tear") end
  local c = reveal.sealCol or { 1, 0.8, 0.5 }
  for _, sh in ipairs(reveal.shards) do
    local ang = math.random() * 6.283
    local sp = 140 + math.random() * 260
    sh.x, sh.y, sh.vx, sh.vy = (math.random() - 0.5) * 50, -10 + (math.random() - 0.5) * 50, math.cos(ang) * sp, math.sin(ang) * sp + 120
    sh.tex:SetColorTexture(math.min(1, c[1] + math.random() * 0.3), math.min(1, c[2] + math.random() * 0.3), math.min(1, c[3] + math.random() * 0.3), 1)
    sh.tex:SetSize(5 + math.random() * 8, 5 + math.random() * 8); sh.tex:SetAlpha(1); sh.tex:Show()
  end
  reveal.shardT = 0.8
  reveal.shakeT, reveal.shakeK = 0.3, 1.5
  reveal.holding, reveal.tear, reveal.picks = false, 0, 0
  startDeal()
end

-- which of our own pictures goes on a set's seal: sheet, cell (0-15, row by row)
local NPC_CELL = { beast = 1, dragonkin = 2, demon = 3, elemental = 4, giant = 5, undead = 6, humanoid = 7, mechanical = 9, creature = 10 }
local function strHash(str)
  local h = 0
  for i = 1, #str do h = (h * 31 + str:byte(i)) % 100003 end
  return h
end
local function emblemFor(setName)
  setName = setName or ""
  local zone = setName:match("^Places in (.+)$")
  if zone then return "Motifs", strHash(zone) % 16 end
  if setName == "All zones" then return "Motifs", 9 end
  local ty = setName:match("^(%a+) bosses$") or setName:match("^(%a+) rares$")
  if ty then
    local cells = CREATURE_CELLS[NPC_CELL[ty:lower()] or 10] or CREATURE_CELLS[10]
    return "Creatures", cells[1 + strHash(setName) % #cells]
  end
  if setName == "Other NPCs" then return "Creatures", 12 end
  if setName == "Legendary items" then return "Slots", 11 end
  local ilvl = setName:match("item level (%d+)")
  if ilvl then return "Slots", (math.floor(tonumber(ilvl) / 10) + 3) % 16 end
  return "Motifs", 5
end
RG.ArcadeEmblem = emblemFor

-- a card a friend showed off (sent through ArcadeDuel's add-on channel)
local toast
function RG.ArcadeShowPull(sender, card, finish)
  if not (card and finish and FNAME[finish]) then return end
  if InCombatLockdown and InCombatLockdown() then return end
  if RG.db and RG.db.arcadeToasts == false then return end
  local now = GetTime and GetTime() or 0
  RG.__pullAt = RG.__pullAt or {}
  if RG.__pullAt[sender or "?"] and now - RG.__pullAt[sender or "?"] < 20 then return end   -- one card per friend every 20 seconds
  RG.__pullAt[sender or "?"] = now
  if not toast then
    toast = CreateFrame("Button", "WaypathArcadeToast", UIParent, "BackdropTemplate")
    toast:SetFrameStrata("DIALOG"); toast:SetPoint("TOP", UIParent, "TOP", 0, -170)
    darkPanel(toast, 340, 200)
    toast.card = makeCard(toast, 112); toast.card:SetPoint("LEFT", 22, 0); toast.card.noTip = true
    toast.head = fs(toast, "head", 12); toast.head:SetPoint("TOPLEFT", toast.card, "TOPRIGHT", 14, -2); toast.head:SetWidth(170); toast.head:SetJustifyH("LEFT"); toast.head:SetTextColor(0.78, 0.74, 0.92)
    toast.name = fs(toast, "title", 14); toast.name:SetPoint("TOPLEFT", toast.head, "BOTTOMLEFT", 0, -8); toast.name:SetWidth(170); toast.name:SetJustifyH("LEFT")
    toast.kind = fs(toast, "body", 12); toast.kind:SetPoint("TOPLEFT", toast.name, "BOTTOMLEFT", 0, -8); toast.kind:SetWidth(170); toast.kind:SetJustifyH("LEFT"); toast.kind:SetTextColor(0.9, 0.86, 0.74)
    toast.hint = fs(toast, "body", 11); toast.hint:SetPoint("BOTTOMRIGHT", -14, 10); toast.hint:SetTextColor(0.6, 0.58, 0.72); toast.hint:SetText("click to close")
    toast.age = 0
    toast:SetScript("OnClick", function(self) self:Hide() end)
    toast:SetScript("OnUpdate", function(self, dt)
      self.age = self.age + dt
      if self.age > 9 then self:Hide() elseif self.age > 8 then self:SetAlpha(math.max(0, 9 - self.age)) end
    end)
  end
  paint(toast.card, card, finish, 1)
  local t = TIER[card.tier][3]
  toast.head:SetText((sender or "Someone") .. " pulled")
  toast.name:SetText(card.name); toast.name:SetTextColor(t[1], t[2], t[3])
  toast.kind:SetText(KIND[card.kind] .. "  ·  " .. FNAME[finish] .. "\n" .. TIER[card.tier][1] .. (cardOdds(card, finish) and ("\nabout 1 in " .. groupDigits(cardOdds(card, finish)) .. " cards") or ""))
  toast.age = 0; toast:SetAlpha(1); toast:Show()
  playSound(nil, nil, "toast")
end

local function showReveal(got, notes, meta)
  if detail then detail:Hide() end   -- a card window left open would sit on top of the pack
  if not reveal then
    reveal = CreateFrame("Frame", "WaypathArcadePack", UIParent, "BackdropTemplate")
    reveal:SetPoint("CENTER", 0, 40); reveal:SetFrameStrata("FULLSCREEN_DIALOG")
    reveal:SetSize(RW, 420)
    reveal:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 })
    reveal:SetBackdropColor(0.055, 0.05, 0.08, 1); reveal:SetBackdropBorderColor(0.42, 0.36, 0.24, 1)
    reveal.title = fs(reveal, "head", 15); reveal.title:SetPoint("TOP", 0, -18); reveal.title:SetTextColor(0.92, 0.86, 0.7)
    reveal.fxFrame = CreateFrame("Frame", nil, reveal); reveal.fxFrame:SetAllPoints(reveal); reveal.fxFrame:SetFrameLevel(lv(reveal) + 1)
    reveal.burst = reveal.fxFrame:CreateTexture(nil, "ARTWORK"); reveal.burst:SetTexture(MEDIA .. "Rays"); reveal.burst:SetBlendMode("ADD"); reveal.burst:Hide()
    reveal.phase, reveal.burstLeft, reveal.burstMax, reveal.burstSpin, reveal.dealT = false, 0, 1, 0, 0
    reveal.cards = {}
    for i = 1, PACK_SIZE do
      local c = makeCard(reveal, RCARD); c:SetFrameLevel(lv(reveal) + 3); c.noTip = true
      local x, y = dealPositions(i)
      c:SetPoint("TOPLEFT", reveal, "TOPLEFT", x, y); reveal.cards[i] = c
      c.new = fs(c, "title", 12, "OVERLAY"); c.new:SetPoint("BOTTOM", c, "TOP", 0, 4)
      local cover = makeCover(c)
      cover:SetScript("OnClick", function() flip(i) end)
    end
    reveal.seal = CreateFrame("Frame", nil, reveal); reveal.seal:SetSize(104, 208); reveal.seal:SetPoint("CENTER", 0, 14); reveal.seal:SetFrameLevel(lv(reveal) + 30)
    reveal.sealGlow = reveal.seal:CreateTexture(nil, "BACKGROUND"); reveal.sealGlow:SetTexture(MEDIA .. "Glow"); reveal.sealGlow:SetBlendMode("ADD"); reveal.sealGlow:SetSize(300, 300); reveal.sealGlow:SetPoint("CENTER")
    reveal.sealGlow:SetVertexColor(1, 0.4, 0.3, 0)
    -- the booster pack: a foil wrapper (drawn by us, tinted per set) with its crimped top strip, which tears off
    reveal.packBack = {}
    for k = 1, 2 do
      local bt = reveal.seal:CreateTexture(nil, "BACKGROUND", nil, -2); bt:SetTexture(MEDIA .. "PackBody"); bt:SetSize(104, 208)
      bt:SetPoint("CENTER", reveal.seal, "CENTER", k == 1 and -18 or 18, -3); bt:SetAlpha(0.8); bt:Hide(); reveal.packBack[k] = bt
    end
    local sealTex = reveal.seal:CreateTexture(nil, "ARTWORK"); sealTex:SetTexture(MEDIA .. "PackBody"); sealTex:SetAllPoints(reveal.seal)
    reveal.sealTex = sealTex
    reveal.strip = reveal.seal:CreateTexture(nil, "ARTWORK", nil, 3); reveal.strip:SetTexture(MEDIA .. "PackTop"); reveal.strip:SetSize(104, 52)
    reveal.strip:SetPoint("TOP", reveal.seal, "TOP", 0, 0)
    -- the set's emblem sits in the medallion
    reveal.emb = reveal.seal:CreateTexture(nil, "OVERLAY", nil, 1); reveal.emb:SetSize(44, 44); reveal.emb:SetPoint("TOP", reveal.seal, "TOP", 0, -84); reveal.emb:Hide()
    reveal.embLight, reveal.embShadow = reveal.emb, reveal.emb   -- (older code hides these by name)
    reveal.sealCount = fs(reveal.seal, "title", 26); reveal.sealCount:SetPoint("CENTER", reveal.emb, "CENTER", 0, 0); reveal.sealCount:SetTextColor(1, 0.95, 0.8); reveal.sealCount:SetText("")
    reveal.packName = fs(reveal.seal, "title", 12); reveal.packName:SetPoint("CENTER", reveal.seal, "TOP", 0, -50); reveal.packName:SetText("WAYPATH"); reveal.packName:SetTextColor(1, 0.96, 0.85)
    reveal.packKind = fs(reveal.seal, "head", 10); reveal.packKind:SetPoint("CENTER", reveal.seal, "TOP", 0, -167); reveal.packKind:SetTextColor(1, 0.96, 0.85)
    reveal.ribbon = reveal.seal:CreateTexture(nil, "OVERLAY"); reveal.ribbon:Hide()
    reveal.ribbonText = fs(reveal.seal, "title", 13); reveal.ribbonText:SetText("")
    reveal.sealHint = fs(reveal.seal, "head", 11); reveal.sealHint:SetPoint("TOP", reveal.seal, "BOTTOM", 0, -8); reveal.sealHint:SetText("Drag across the top to rip it open, or click it three times"); reveal.sealHint:SetTextColor(0.7, 0.67, 0.6)
    reveal.seal:EnableMouse(true)
    reveal.sealCol = { 1, 1, 1 }
    reveal.sealInfo = fs(reveal.seal, "body", 12); reveal.sealInfo:SetPoint("TOP", reveal.seal, "BOTTOM", 0, -30); reveal.sealInfo:SetWidth(RW - 120); reveal.sealInfo:SetJustifyH("CENTER"); reveal.sealInfo:SetTextColor(0.78, 0.74, 0.92)
    reveal.cracks = {}
    reveal.shards = {}
    for i = 1, 14 do
      local st = reveal.fxFrame:CreateTexture(nil, "OVERLAY"); st:SetColorTexture(1, 0.8, 0.5, 1); st:SetSize(8, 8); st:Hide()
      reveal.shards[i] = { tex = st, x = 0, y = 0, vx = 0, vy = 0 }
    end
    reveal.tear, reveal.picks, reveal.pickIdle, reveal.holdT, reveal.moved, reveal.hx, reveal.hy = 0, 0, 0, 0, 0, 0, 0
    reveal.holding, reveal.record, reveal.shardT, reveal.shakeT, reveal.shakeK = false, false, 0, 0, 1
    -- hold and drag (or hold a moment) to tear the seal; three plain clicks chip it open too
    reveal.seal:SetScript("OnMouseDown", function()
      if reveal.phase ~= "seal" then return end
      reveal.holding, reveal.holdT, reveal.moved = true, 0, 0
      reveal.hx, reveal.hy = cursorXY()
    end)
    reveal.seal:SetScript("OnMouseUp", function()
      if reveal.phase ~= "seal" or not reveal.holding then return end
      reveal.holding = false
      if reveal.holdT < 0.25 and reveal.moved < 8 then
        reveal.picks, reveal.pickIdle = reveal.picks + 1, 0
        playSound(nil, nil, "pick")
        if reveal.picks >= 3 then tearOpen() end
      end
    end)
    reveal.share = gbtn(reveal, "Show off", 100, 26, function()
      local bg
      for _, g in ipairs(reveal.got or {}) do if not bg or g.finish * 10 + g.card.tier > bg.finish * 10 + bg.card.tier then bg = g end end
      if not bg then return end
      local msg = "Waypath+ cards: I pulled " .. bg.card.name .. " (" .. FNAME[bg.finish] .. ")" .. (bg.odds and (", about 1 in " .. groupDigits(bg.odds) .. " cards") or "") .. "!"
      -- players in your group or guild with Waypath+ get the card itself; the chat box is filled in for everyone else
      local sent = RG.ArcadeShareCard and RG.ArcadeShareCard(bg.card, bg.finish) or 0
      if sent > 0 and RG.Print then RG.Print("Shown to the Waypath+ players in your " .. (sent > 1 and "group and guild." or "group or guild.")) end
      if ChatFrame_OpenChat then ChatFrame_OpenChat(msg) elseif RG.Print then RG.Print(msg) end
    end)
    reveal.share:SetPoint("BOTTOM", 290, 18); reveal.share:Hide()
    reveal.snd = gbtn(reveal, "Sound: On", 84, 22, function(self)
      local a = store(); if not a then return end
      a.mute = not a.mute
      self:SetText(a.mute and "Sound: Off" or "Sound: On")
    end)
    reveal.snd:SetPoint("BOTTOM", -300, 20)
    reveal.sum = fs(reveal, "body", 14); reveal.sum:SetPoint("TOP", 0, -276); reveal.sum:SetWidth(RW - 80); reveal.sum:SetTextColor(0.9, 0.86, 0.74)
    reveal.all = gbtn(reveal, "Turn all", 120, 26, function()
      for i = 1, PACK_SIZE do
        local function go() if reveal:IsShown() then flip(i) end end
        if C_Timer and C_Timer.After then C_Timer.After((i - 1) * 0.5 + (i == PACK_SIZE and 0.5 or 0), go) else go() end
      end
    end)
    reveal.all:SetPoint("BOTTOM", -150, 18)
    reveal.again = gbtn(reveal, "Open another pack", 170, 26, function() if frame and frame.buyNow then frame.buyNow() end end, true)
    reveal.again:SetPoint("BOTTOM", 0, 18)
    reveal.ok = gbtn(reveal, "Skip", 120, 26, function() reveal:Hide(); RG.ArcadeRefresh(true) end)
    reveal.ok:SetPoint("BOTTOM", 150, 18)
    tinsert(UISpecialFrames, "WaypathArcadePack")
    -- a dark veil over the collection window, so nothing of it peeks out around the pack
    local dim = CreateFrame("Frame", nil, UIParent)
    dim:SetFrameStrata("FULLSCREEN_DIALOG"); dim:SetFrameLevel(math.max(0, lv(reveal) - 1))
    local dt = dim:CreateTexture(nil, "BACKGROUND"); dt:SetAllPoints(dim); dt:SetColorTexture(0.03, 0.03, 0.06, 1)
    reveal.dim = dim
    reveal:HookScript("OnShow", function()
      dim:ClearAllPoints()
      if frame and frame:IsShown() then dim:SetAllPoints(frame) else dim:SetSize(1, 1); dim:SetPoint("CENTER") end
      dim:Show()
    end)
    reveal:HookScript("OnHide", function() dim:Hide() end)
    -- one update loop: the seal pulses, the cards are dealt, the burst fades
    reveal:SetScript("OnUpdate", function(self, dt)
      local t = GetTime and GetTime() or 0
      if self.phase == "seal" then
        if self.holding then
          self.holdT = self.holdT + dt
          local x, y = cursorXY()
          local d = math.sqrt((x - self.hx) ^ 2 + (y - self.hy) ^ 2)
          if d > self.moved then self.moved = d end
          self.tear = math.max(self.tear, math.min(1, math.max(d / 80, (self.holdT - 0.15) / 1.1)))
        else
          self.tear = math.max(0, self.tear - dt * 1.4)
        end
        self.pickIdle = self.pickIdle + dt
        if self.pickIdle > 2 and self.picks > 0 then self.picks = 0 end
        if self.tear >= 1 then tearOpen(); return end
        local tt = math.max(self.tear, self.picks / 3 * 0.85)
        local k = 1 + 0.02 * math.sin(t * 4) + 0.12 * tt
        self.seal:SetSize(104 * k, 208 * k)
        self.seal:ClearAllPoints(); self.seal:SetPoint("CENTER", math.sin(t * 55) * 2 * tt, 14 + math.cos(t * 47) * 1.5 * tt + 3 * math.sin(t * 1.6))
        -- the strip lifts, tilts and pulls away as the tear goes on
        self.strip:SetSize(104 * k, 52 * k)
        self.strip:ClearAllPoints(); self.strip:SetPoint("TOP", self.seal, "TOP", 12 * tt, 20 * tt)
        if self.strip.SetRotation then self.strip:SetRotation(-0.35 * tt) end
        self.sealGlow:SetAlpha(0)
        local c = self.sealCol
        local r, g, b = c[1] + (1 - c[1]) * tt * 0.4, c[2] + (1 - c[2]) * tt * 0.4, c[3] + (1 - c[3]) * tt * 0.4
        self.sealTex:SetVertexColor(r, g, b, 1); self.strip:SetVertexColor(r, g, b, 1)
      elseif self.phase == "deal" then
        self.dealT = self.dealT + dt
        local all = true
        for i = 1, PACK_SIZE do
          local k = math.max(0, math.min(1, (self.dealT - (i - 1) * 0.09) / 0.4))
          local e = 1 - (1 - k) ^ 3
          local x, y = dealPositions(i)
          local cx = (RW - RCARD) / 2
          local c = self.cards[i]
          c:ClearAllPoints(); c:SetPoint("TOPLEFT", self, "TOPLEFT", cx + (x - cx) * e, y)
          c:SetAlpha(e)
          if k < 1 then all = false end
        end
        if all then self.phase = false end
      end
      if type(self.sealFade) == "number" and self.sealFade > 0 then
        -- the strip is thrown off and the wrapper drops away
        self.sealFade = self.sealFade - dt
        local k = 1 - math.max(0, self.sealFade) / 0.55
        self.strip:ClearAllPoints(); self.strip:SetPoint("TOP", self.seal, "TOP", 40 + 150 * k, 20 + 120 * k - 160 * k * k)
        if self.strip.SetRotation then self.strip:SetRotation(-0.35 - 1.6 * k) end
        self.strip:SetAlpha(1 - k)
        self.seal:SetAlpha(math.max(0, 1 - k * 1.4))
        if self.sealFade <= 0 then self.sealFade = nil; self.seal:Hide(); self.seal:SetAlpha(1); self.strip:SetAlpha(1) end
      end
      if self.shakeT > 0 then
        self.shakeT = self.shakeT - dt
        local m = 3.5 * self.shakeK * math.max(0, self.shakeT) / 0.35
        self:ClearAllPoints(); self:SetPoint("CENTER", (math.random() - 0.5) * 2 * m, 40 + (math.random() - 0.5) * 2 * m)
        if self.shakeT <= 0 then self:ClearAllPoints(); self:SetPoint("CENTER", 0, 40) end
      end
      if self.shardT > 0 then
        self.shardT = self.shardT - dt
        for _, sh in ipairs(self.shards) do
          sh.vy = sh.vy - 900 * dt; sh.x = sh.x + sh.vx * dt; sh.y = sh.y + sh.vy * dt
          sh.tex:ClearAllPoints(); sh.tex:SetPoint("CENTER", self, "CENTER", sh.x, sh.y)
          sh.tex:SetAlpha(math.max(0, self.shardT / 0.8))
          if self.shardT <= 0 then sh.tex:Hide() end
        end
      end
      if self.burstLeft and self.burstLeft > 0 then
        self.burstLeft = self.burstLeft - dt
        local k = math.max(0, self.burstLeft / self.burstMax)
        self.burst:SetAlpha(k * k)
        self.burstSpin = (self.burstSpin or 0) + dt * 0.5
        if self.burst.SetRotation then self.burst:SetRotation(self.burstSpin) end
        if self.burstLeft <= 0 then self.burst:Hide() end
      end
    end)
  end
  reveal.got, reveal.flipped, reveal.notes, reveal.meta, reveal.record = got, 0, notes, meta, false
  meta = meta or {}
  -- what kind of seal this is: reward, many at once, the day's first, or the featured set's colours
  local col, title, info = { 1, 1, 1 }, "Open the pack", {}
  if meta.bonus then
    col, title = { 0.85, 0.6, 1 }, "Reward pack"
    info[#info + 1] = "|cffd9a8ffReward pack|r  ·  a rare and a holo or better inside"
  elseif meta.many then
    col, title = { 1, 0.85, 0.45 }, meta.many.count .. " packs"
    info[#info + 1] = GOLDHEX .. meta.many.count .. " packs at once|r  ·  the five best cards are shown"
  else
    if meta.featured then
      local h = 0
      for ch in meta.featured:gmatch(".") do h = (h * 31 + ch:byte()) % 997 end
      local r, g, b = hsv(h / 997, 0.5, 1)
      col = { r, g, b }
      info[#info + 1] = "Featured: " .. GOLDHEX .. meta.featured .. "|r  ·  more of its cards inside"
    end
    if meta.daily then title = "Daily pack"; info[#info + 1] = "|cff7be08aDaily pack|r  ·  day " .. (meta.streak or 1) .. " in a row" end
  end
  if not meta.many then
    local pb = meta.pityBefore or 0
    if meta.bonus or pb >= PITY then info[#info + 1] = "|cffd9a8ffThis pack holds a holo or full art|r"
    else info[#info + 1] = "Holo or full art guaranteed within " .. (PITY - pb) .. " pack" .. (PITY - pb == 1 and "" or "s") end
  end
  reveal.sealCol = col
  reveal.sealTex:SetVertexColor(col[1], col[2], col[3], 1); reveal.strip:SetVertexColor(col[1], col[2], col[3], 1)
  -- the wrapper: tinted per set, with the set's emblem in the medallion; a reward pack is gold, several packs fan out
  reveal.emb:Hide(); reveal.sealCount:SetText(""); reveal.ribbon:Hide(); reveal.ribbonText:SetText("")
  for _, bt in ipairs(reveal.packBack) do bt:SetVertexColor(col[1] * 0.7, col[2] * 0.7, col[3] * 0.7, 1); bt:SetShown(meta.many and true or false) end
  local kind = "MIXED"
  if meta.bonus then kind = "REWARD"
  elseif meta.many then kind = "x" .. meta.many.count
  elseif meta.daily then kind = "DAILY"
  elseif meta.featured then
    local f = meta.featured
    if f:find("^Places") or f == "All zones" then kind = "PLACES"
    elseif f:find("bosses") or f:find("rares") or f == "Other NPCs" then kind = "NPCS"
    else kind = "ITEMS" end
  end
  reveal.packKind:SetText(kind)
  if meta.many then reveal.sealCount:SetText("x" .. meta.many.count)
  elseif meta.bonus then reveal.emb:SetTexture(MEDIA .. "Rune"); reveal.emb:SetTexCoord(0, 1, 0, 1); reveal.emb:SetVertexColor(1, 0.9, 0.5, 0.95); reveal.emb:Show()
  elseif meta.featured then
    local sheet, cell = emblemFor(meta.featured)
    local c0, r0 = cell % 4, math.floor(cell / 4)
    reveal.emb:SetTexture(MEDIA .. sheet); reveal.emb:SetTexCoord(c0 * 0.25, (c0 + 1) * 0.25, r0 * 0.25, (r0 + 1) * 0.25)
    reveal.emb:SetVertexColor(math.min(1, col[1] + 0.25), math.min(1, col[2] + 0.25), math.min(1, col[3] + 0.25), 0.95); reveal.emb:Show()
  else reveal.emb:SetTexture(MEDIA .. "Rune"); reveal.emb:SetTexCoord(0, 1, 0, 1); reveal.emb:SetVertexColor(0.9, 0.9, 1, 0.8); reveal.emb:Show() end
  reveal.sealFade = nil; reveal.seal:SetAlpha(1)
  reveal.sealInfo:SetText(table.concat(info, "\n"))
  reveal.title:SetText(title)
  reveal.sum:SetText("")
  reveal.all:Show(); reveal.share:Hide(); reveal.ok:SetText("Skip")
  do local a = store(); reveal.snd:SetText(a and a.mute and "Sound: Off" or "Sound: On") end
  reveal.burst:Hide(); reveal.burstLeft = 0
  reveal.tear, reveal.picks, reveal.holding, reveal.shardT, reveal.shakeT = 0, 0, false, 0, 0
  for _, sh in ipairs(reveal.shards) do sh.tex:Hide() end
  reveal:ClearAllPoints(); reveal:SetPoint("CENTER", 0, 40)
  reveal:Show()
  reveal.phase = "seal"
  reveal.seal:ClearAllPoints(); reveal.seal:SetPoint("CENTER", 0, 14)
  reveal.seal:Show(); reveal.seal:SetSize(104, 208); reveal.seal:SetAlpha(1)
  reveal.strip:ClearAllPoints(); reveal.strip:SetPoint("TOP", reveal.seal, "TOP", 0, 0); reveal.strip:SetSize(104, 52)
  if reveal.strip.SetRotation then reveal.strip:SetRotation(0) end; reveal.strip:SetAlpha(1); reveal.sealTex:SetAlpha(1)
  for i, g in ipairs(got) do
    local w = reveal.cards[i]
    paint(w, g.card, g.finish, 1)
    w.new:SetText("")
    local c = w.cover
    c.flipping = false; c:SetScript("OnUpdate", nil); c:SetWidth(w.cw); c:Show()
    c.peel, c.lift, c.holding = 0, 0, false; c.fold:Hide(); c.peek:Hide(); c:SetHeight(w.ch); c.tex:SetTexCoord(0, 1, 0, CARD_V)
    c:ClearAllPoints(); c:SetPoint("CENTER", 0, 0); c.cued = false
    c.rare = (g.finish >= 3 or g.card.tier == 6) and true or false
    c.peekCol = g.card.tier == 6 and { 1, 0.2, 0.35 } or (g.finish == 4 and { 1, 0.75, 0.2 } or (g.finish == 3 and { 0.7, 0.35, 0.95 } or (g.finish == 2 and { 0.3, 0.55, 1 } or { 0.6, 0.6, 0.65 })))
    if RG.CardBackName then c.tex:SetTexture(MEDIA .. RG.CardBackName()) end
    if g.finish >= 3 or g.card.tier == 6 then c.glow:Show(); anim[c] = coverAnim else anim[c] = nil; c.glow:Hide() end
    w:SetAlpha(0)
  end
  reveal.again:SetEnabled(afford() and true or false)
end

-- ---------------------------------------------------------------------------
-- Card detail view
-- ---------------------------------------------------------------------------
local function say(text)
  if frame and frame:IsShown() and frame.msg then frame.msg:SetText(text or "") elseif RG.Print then RG.Print(text) end
end
RG.ArcadeMsg = say

local function refreshDetail()
  if not (detail and detail:IsShown() and detail.data) then return end
  local a = store()
  local c = detail.data
  local slot = a.cards[c.key or c.name] or {}
  local f = detail.finish
  if (slot[f] or 0) == 0 then f = bestFinish(a, c.id) or 1; detail.finish = f end
  paint(detail.card, c, bestFinish(a, c.id) and f or nil, owned(a, c.id))
  local t = TIER[c.tier][3]
  detail.name:SetText(c.name); detail.name:SetTextColor(t[1], t[2], t[3])
  detail.kind:SetText(KIND[c.kind] .. "  ·  " .. TIER[c.tier][1])
  detail.flavor:SetText(c.text or "")
  detail.info:SetText("Set: |cffffffff" .. setOf(c) .. "|r\nPower: |cffffffff" .. power(c, f) .. "|r" .. (a.duelCard == (c.key or c.name) and "   |cff7be08aYour duel card|r" or "")
    .. "\nOwned: |cffffffff" .. owned(a, c.id) .. "|r")
  for k = 1, 4 do
    local n = slot[k] or 0
    local b = detail.prints[k]
    b:SetText(FNAME[k] .. " x" .. n)
    b:SetEnabled(n > 0); b:SetActive(k == f)
  end
  detail.pin:SetText(isPinned(a, c) and "Remove from showcase" or "Add to showcase")
  detail.duel:SetText(a.duelCard == (c.key or c.name) and "Duel card (set)" or "Use for duels")
  detail.offer:SetEnabled(c.kind ~= 4 and (slot[f] or 0) >= 2)
end

local function openDetail(c)
  if reveal and reveal:IsShown() then return end   -- finish opening the pack first
  local a = store()
  if not (a and c and owned(a, c.id) > 0) then return end
  if not detail then
    detail = CreateFrame("Frame", "WaypathArcadeCard", UIParent, "BackdropTemplate")
    detail:SetPoint("CENTER", 100, 0); detail:SetFrameStrata("FULLSCREEN_DIALOG")
    darkPanel(detail, 640, 420)
    tinsert(UISpecialFrames, "WaypathArcadeCard")
    detail.card = makeCard(detail, 230); detail.card:SetPoint("TOPLEFT", 30, -40); detail.card:SetFrameLevel(lv(detail) + 3); detail.card.noTip = true
    local X0 = 290
    detail.name = fs(detail, "title", 20); detail.name:SetPoint("TOPLEFT", X0, -36); detail.name:SetWidth(320); detail.name:SetJustifyH("LEFT"); detail.name:SetWordWrap(true)
    detail.kind = fs(detail, "head", 12); detail.kind:SetPoint("TOPLEFT", detail.name, "BOTTOMLEFT", 0, -4); detail.kind:SetTextColor(0.7, 0.66, 0.85)
    local rule = detail:CreateTexture(nil, "ARTWORK"); rule:SetTexture(MEDIA .. "Rule"); rule:SetSize(320, 14); rule:SetPoint("TOPLEFT", detail.kind, "BOTTOMLEFT", 0, -6)
    detail.flavor = fs(detail, "body", 14); detail.flavor:SetPoint("TOPLEFT", rule, "BOTTOMLEFT", 0, -6); detail.flavor:SetWidth(320); detail.flavor:SetJustifyH("LEFT"); detail.flavor:SetTextColor(0.86, 0.82, 0.7); detail.flavor:SetSpacing(3)
    detail.info = fs(detail, "body", 13); detail.info:SetPoint("TOPLEFT", detail.flavor, "BOTTOMLEFT", 0, -10); detail.info:SetWidth(320); detail.info:SetJustifyH("LEFT"); detail.info:SetTextColor(0.7, 0.68, 0.85); detail.info:SetSpacing(3)
    local close = gbtn(detail, "X", 26, 24, function() detail:Hide() end); close:SetPoint("TOPRIGHT", -14, -14)
    detail.prints = {}
    for k = 1, 4 do
      local b = gbtn(detail, "", 80, 24, function() detail.finish = k; refreshDetail() end)
      b:SetPoint("BOTTOMLEFT", X0 + (k - 1) * 82, 118)
      detail.prints[k] = b
    end
    detail.pin = gbtn(detail, "Showcase", 160, 26, function()
      local on = RG.ArcadePin(detail.data); say(on and (detail.data.name .. " added to your showcase.") or (detail.data.name .. " removed from your showcase.")); refreshDetail(); RG.ArcadeRefresh(true)
    end)
    detail.pin:SetPoint("BOTTOMLEFT", X0, 80)
    detail.duel = gbtn(detail, "Use for duels", 160, 26, function()
      local a2 = store(); a2.duelCard = detail.data.key or detail.data.name; say(detail.data.name .. " will fight your duels."); refreshDetail()
    end)
    detail.duel:SetPoint("BOTTOMLEFT", X0 + 164, 80)
    detail.link = gbtn(detail, "Link in chat", 160, 26, function()
      local c2 = detail.data
      local text = "[Waypath card: " .. c2.name .. " (" .. FNAME[detail.finish] .. ")]"
      if ChatEdit_InsertLink then pcall(ChatEdit_InsertLink, text) elseif DEFAULT_CHAT_FRAME and DEFAULT_CHAT_FRAME.editBox then DEFAULT_CHAT_FRAME.editBox:Insert(text) end
    end)
    detail.link:SetPoint("BOTTOMLEFT", X0, 44)
    detail.offer = gbtn(detail, "Offer to group", 160, 26, function()
      local ok, msg = RG.ArcadeOffer(detail.data, detail.finish); say(msg)
    end)
    detail.offer:SetPoint("BOTTOMLEFT", X0 + 164, 44)
  end
  detail.data, detail.finish = c, bestFinish(a, c.id) or 1
  detail:Show(); refreshDetail()
end

-- ---------------------------------------------------------------------------
-- Main window
-- ---------------------------------------------------------------------------
local MODES = { { "cards", "Collection" }, { "sets", "Sets" }, { "today", "Today" }, { "trade", "Trade" }, { "stats", "Ledger" } }

local function cell_click(self, btn)
  local c = self.card
  if not c then return end
  local a = store()
  if owned(a, c.id) == 0 then return end
  if btn == "RightButton" then
    local on = RG.ArcadePin(c); say(on and (c.name .. " added to your showcase.") or (c.name .. " removed from your showcase."))
    RG.ArcadeRefresh(true)
  else openDetail(c) end
end

local function build()
  frame = CreateFrame("Frame", "WaypathArcade", UIParent, "BackdropTemplate")
  frame:SetPoint("CENTER"); frame:SetFrameStrata("DIALOG")
  frame:SetMovable(true); frame:EnableMouse(true); frame:RegisterForDrag("LeftButton")
  frame:SetScript("OnDragStart", frame.StartMoving); frame:SetScript("OnDragStop", frame.StopMovingOrSizing)
  frame.night = darkPanel(frame, WINW, WINH)
  frame:SetClampedToScreen(true)
  tinsert(UISpecialFrames, "WaypathArcade")
  -- a slowly turning circle behind the cards, and drifting motes
  frame.circle = frame:CreateTexture(nil, "BACKGROUND", nil, 3); frame.circle:SetTexture(MEDIA .. "Rune"); frame.circle:SetBlendMode("ADD")
  frame.circle:SetSize(640, 640); frame.circle:SetPoint("CENTER", frame, "CENTER", 0, -30); frame.circle:SetVertexColor(0.9, 0.72, 0.38, 0.09)
  frame.motes = {}
  for i = 1, 12 do
    local m = frame:CreateTexture(nil, "BACKGROUND", nil, 4); m:SetTexture("Interface\\Cooldown\\star4"); m:SetBlendMode("ADD"); m:SetSize(10 + (i % 3) * 5, 10 + (i % 3) * 5)
    m.px, m.py, m.sp = math.random(), math.random(), 0.01 + math.random() * 0.02
    frame.motes[i] = m
  end
  frame.open = 1
  frame:SetScript("OnShow", function(self) self.open = 0; self:SetAlpha(0) end)
  frame:SetScript("OnUpdate", function(self, dt)
    local t = GetTime and GetTime() or 0
    if self.open and self.open < 1 then self.open = math.min(1, self.open + dt / 0.35); self:SetAlpha(self.open) end
    if self.circle.SetRotation then self.circle:SetRotation((t * 0.025) % 6.2832) end
    for _, m in ipairs(self.motes) do
      m.py = m.py + m.sp * dt; if m.py > 1 then m.py = 0; m.px = math.random() end
      m:ClearAllPoints(); m:SetPoint("CENTER", self, "BOTTOMLEFT", (m.px + 0.015 * math.sin(t * 0.7 + m.px * 9)) * WINW, m.py * WINH)
      m:SetAlpha(0.5 * math.sin(m.py * 3.1416) * (0.6 + 0.4 * math.sin(t * 2 + m.px * 20)))
    end
  end)
  -- title plate
  local plate = frame:CreateTexture(nil, "ARTWORK"); plate:SetTexture(MEDIA .. "Plate"); plate:SetSize(380, 48); plate:SetPoint("TOP", 0, -12)
  frame.title = fs(frame, "title", 22); frame.title:SetPoint("CENTER", plate, "CENTER", 0, 0); frame.title:SetText("WAYPATH CARDS"); frame.title:SetTextColor(GOLDC[1], GOLDC[2], GOLDC[3])
  frame.tagline = fs(frame, "body", 14); frame.tagline:SetPoint("TOP", plate, "BOTTOM", 0, -4); frame.tagline:SetText("a collector's grimoire"); frame.tagline:SetTextColor(0.8, 0.76, 0.95)
  frame.coinIcon = frame:CreateTexture(nil, "ARTWORK"); frame.coinIcon:SetTexture("Interface\\Icons\\INV_Misc_Coin_01"); frame.coinIcon:SetSize(20, 20); frame.coinIcon:SetTexCoord(0.07, 0.93, 0.07, 0.93); frame.coinIcon:SetPoint("TOPLEFT", 30, -22)
  frame.coins = fs(frame, "head", 16); frame.coins:SetPoint("LEFT", frame.coinIcon, "RIGHT", 6, 0)
  frame.free = fs(frame, "head", 12); frame.free:SetPoint("TOPLEFT", frame.coinIcon, "BOTTOMLEFT", 0, -3); frame.free:SetTextColor(0.5, 0.88, 0.6)
  local close = gbtn(frame, "X", 28, 24, function() frame:Hide() end); close:SetPoint("TOPRIGHT", -18, -18)
  local rule = frame:CreateTexture(nil, "ARTWORK"); rule:SetTexture(MEDIA .. "Rule"); rule:SetSize(360, 14); rule:SetPoint("TOP", frame.tagline, "BOTTOM", 0, -4)
  frame.sub = fs(frame, "body", 13); frame.sub:SetPoint("TOP", rule, "BOTTOM", 0, -1); frame.sub:SetSpacing(1); frame.sub:SetTextColor(0.94, 0.91, 1); frame.sub:SetJustifyH("CENTER"); frame.sub:SetWidth(WINW - 120)

  -- tabs
  frame.modes = {}
  local tw = 112
  for i, m in ipairs(MODES) do
    local t = gtab(frame, m[2]:upper(), tw, function() view.mode = m[1]; view.set = (m[1] == "cards") and view.set or nil; RG.ArcadeRefresh(true) end)
    t:SetPoint("TOP", frame, "TOP", (i - 3) * (tw + 6), -128)
    frame.modes[m[1]] = t
  end
  -- filters
  frame.filters = {}
  local labels = { [0] = "All", "Items", "NPCs", "Places", "Raiders" }
  for k = 0, 4 do
    frame.filters[k] = gbtn(frame, labels[k], 60, 24, function() view.kind = k; view.page = 1; view.showcase = false; view.mode = "cards"; RG.ArcadeRefresh(true) end)
    frame.filters[k]:SetPoint("TOPLEFT", 34 + k * 62, -160)
  end
  frame.showcase = gbtn(frame, "Showcase", 80, 24, function() view.showcase = not view.showcase; view.kind = 0; view.page = 1; view.mode = "cards"; RG.ArcadeRefresh(true) end)
  frame.showcase:SetPoint("TOPLEFT", 34 + 5 * 62, -160)
  frame.sortBtn = gbtn(frame, "Sort: Collection", 124, 24, function() view.sort = view.sort % #SORTS + 1; view.page = 1; RG.ArcadeRefresh(true) end)
  frame.sortBtn:SetPoint("TOPRIGHT", -34, -160)
  frame.showBtn = gbtn(frame, "Show: All", 100, 24, function() view.show = view.show % #SHOWS + 1; view.page = 1; RG.ArcadeRefresh(true) end)
  frame.showBtn:SetPoint("RIGHT", frame.sortBtn, "LEFT", -6, 0)
  frame.searchBox = CreateFrame("EditBox", nil, frame, "BackdropTemplate")
  frame.searchBox:SetSize(92, 24); frame.searchBox:SetPoint("RIGHT", frame.showBtn, "LEFT", -6, 0)
  frame.searchBox:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }); frame.searchBox:SetBackdropColor(0.03, 0.02, 0.07, 0.95); frame.searchBox:SetBackdropBorderColor(0.45, 0.38, 0.25, 0.9)
  setfont(frame.searchBox, "body", 14); frame.searchBox:SetTextColor(0.95, 0.9, 0.78); frame.searchBox:SetTextInsets(8, 6, 0, 0)
  frame.searchBox:SetAutoFocus(false); frame.searchBox:SetMaxLetters(30)
  frame.searchBox:SetScript("OnTextChanged", function(self) local t = self:GetText() or ""; if t ~= view.search then view.search = t; view.page = 1; RG.ArcadeRefresh(true) end end)
  frame.searchBox:SetScript("OnEscapePressed", function(self) self:ClearFocus() end)
  frame.searchHint = fs(frame.searchBox, "body", 14); frame.searchHint:SetPoint("LEFT", 8, 0); frame.searchHint:SetText("Search"); frame.searchHint:SetTextColor(0.72, 0.68, 0.85)

  -- the binder
  cells = {}
  local gx0 = (WINW - ((COLS - 1) * GRIDX + CELLW)) / 2
  for i = 1, COLS * ROWS do
    local c = makeCard(frame, CELLW)
    c:SetFrameLevel(lv(frame) + 3)
    c:SetPoint("TOPLEFT", frame, "TOPLEFT", gx0 + ((i - 1) % COLS) * GRIDX, -196 - math.floor((i - 1) / COLS) * GRIDY)
    c.onCard = cell_click
    cells[i] = c
  end
  frame.cells = cells
  -- the text screens (Sets, Today, Trade, Ledger)
  frame.panel = fs(frame, "body", 14); frame.panel:SetPoint("TOPLEFT", 40, -200); frame.panel:SetWidth(WINW - 80); frame.panel:SetJustifyH("LEFT"); frame.panel:SetJustifyV("TOP"); frame.panel:SetSpacing(6)
  frame.panel:SetTextColor(0.9, 0.86, 0.74)
  frame.rows = {}
  for i = 1, 14 do
    local b = CreateFrame("Button", nil, frame, "BackdropTemplate")
    b:SetSize(WINW - 80, 26); b:SetPoint("TOPLEFT", 40, -200 - (i - 1) * 30)
    b:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }); b:SetBackdropColor(0.07, 0.05, 0.14, 0.9); b:SetBackdropBorderColor(0.4, 0.33, 0.2, 0.8)
    b.left = fs(b, "body", 14); b.left:SetPoint("LEFT", 10, 0); b.left:SetJustifyH("LEFT")
    b.right = fs(b, "head", 12); b.right:SetPoint("RIGHT", -10, 0); b.right:SetJustifyH("RIGHT"); b.right:SetTextColor(GOLDC[1], GOLDC[2], GOLDC[3])
    b:SetScript("OnEnter", function(self) self:SetBackdropColor(0.13, 0.09, 0.22, 0.95); self:SetBackdropBorderColor(GOLDC[1], GOLDC[2], GOLDC[3], 1) end)
    b:SetScript("OnLeave", function(self) self:SetBackdropColor(0.07, 0.05, 0.14, 0.9); self:SetBackdropBorderColor(0.4, 0.33, 0.2, 0.8) end)
    b:SetScript("OnClick", function(self) if self.act then self.act() end end)
    frame.rows[i] = b
  end

  -- footer
  frame.msg = fs(frame, "body", 14); frame.msg:SetPoint("BOTTOMLEFT", 40, 56); frame.msg:SetWidth(480); frame.msg:SetJustifyH("LEFT"); frame.msg:SetTextColor(0.9, 0.84, 0.62)
  frame.prev = gbtn(frame, "<", 36, 24, function() if view.mode == "sets" then view.setPage = math.max(0, (view.setPage or 0) - 1) else view.page = view.page - 1 end; RG.ArcadeRefresh(true) end)
  frame.prev:SetPoint("BOTTOM", 230, 58)
  frame.next = gbtn(frame, ">", 36, 24, function() if view.mode == "sets" then view.setPage = (view.setPage or 0) + 1 else view.page = view.page + 1 end; RG.ArcadeRefresh(true) end)
  frame.next:SetPoint("BOTTOM", 330, 58)
  frame.pageText = fs(frame, "head", 14); frame.pageText:SetPoint("BOTTOM", 280, 62); frame.pageText:SetTextColor(0.92, 0.88, 1)
  frame.buyNow = function(many)
    local got, free, notes, meta
    if many == true then got, free, notes, meta = RG.ArcadeOpenMany() else got, free, notes, meta = RG.ArcadeOpenPack() end
    if not got then say(free or "") return end
    if meta and meta.bonus then playSound(nil, nil, "reward") end
    showReveal(got, notes, meta); RG.ArcadeRefresh(true)
  end
  frame.buy = gbtn(frame, "Break a pack", 250, 34, function() frame.buyNow() end, true)
  frame.buy:SetPoint("BOTTOM", 0, 20)
  frame.buyAll = gbtn(frame, "Break all", 110, 28, function() frame.buyNow(true) end)
  frame.buyAll:SetPoint("BOTTOM", 335, 23); frame.buyAll:Hide()
  frame.duel = gbtn(frame, "Duel for coins", 150, 28, function()
    local win, mine, foe, mf, ff, prize, goal = RG.ArcadeDuel()
    if win == nil then say(mine or "") return end
    say((win and ("Won! +" .. prize .. " coins.") or "Lost.") .. " " .. mine.name .. " (" .. FNAME[mf] .. ") vs " .. foe.name .. " (" .. FNAME[ff] .. ")" .. (goal and ("  ·  " .. goal) or ""))
    RG.ArcadeRefresh(true)
  end)
  frame.duel:SetPoint("BOTTOM", -200, 23)
  frame.sell = gbtn(frame, "Sell extras", 150, 28, function()
    local n, coins, g = RG.ArcadeSellExtras()
    say(n > 0 and ("Sold " .. n .. " extra cards for " .. coins .. " coins. One of each print is kept." .. (g and ("  ·  " .. g) or "")) or "No extras to sell: you keep one of each print.")
    RG.ArcadeRefresh(true)
  end)
  frame.sell:SetPoint("BOTTOM", 200, 23)
  frame.arena = gbtn(frame, "Arena", 96, 28, function() if RG.ShowBattle then frame:Hide(); RG.ShowBattle() end end)
  frame.arena:SetPoint("BOTTOM", -340, 23)
  -- fit small screens
  local ph = UIParent and UIParent.GetHeight and UIParent:GetHeight()
  if type(ph) == "number" and ph > 0 and ph < WINH + 30 then frame:SetScale(math.max(0.6, (ph - 30) / WINH)) end
end

local function categoryLine(a)
  local have, tot = { 0, 0, 0, 0 }, { 0, 0, 0, 0 }
  for _, c in ipairs(CARDS) do tot[c.kind] = tot[c.kind] + 1; if owned(a, c.id) > 0 then have[c.kind] = have[c.kind] + 1 end end
  return string.format("Items %d/%d  ·  NPCs %d/%d  ·  Places %d/%d  ·  Raiders %d/%d", have[1], tot[1], have[2], tot[2], have[3], tot[3], have[4], tot[4])
end

local function showRows(n) for i, b in ipairs(frame.rows) do b:SetShown(i <= n) end end

function RG.ArcadeRefresh(keepMsg)
  if not (frame and frame:IsShown()) then return end
  local a, own, total, prints = RG.ArcadeStats()
  dailyCheck()
  frame.coins:SetText(GOLDHEX .. (a.coins or 0) .. "|r")
  frame.free:SetText((a.free or 0) > 0 and ((a.free) .. " free pack" .. (a.free > 1 and "s" or "")) or "")
  frame.sub:SetText(own .. " of " .. total .. " cards  ·  " .. prints .. " prints  ·  " .. (a.wins or 0) .. " duel wins\n" .. categoryLine(a))
  if keepMsg ~= true then frame.msg:SetText("") end
  local cards = view.mode == "cards"
  for _, cell in ipairs(cells) do if not cards then cell:Hide() end end
  frame.panel:SetText("")
  frame.searchBox:SetShown(cards); frame.searchHint:SetShown(cards and (view.search or "") == "")
  frame.sortBtn:SetShown(cards); frame.showBtn:SetShown(cards)
  frame.sortBtn:SetText("Sort: " .. SORTS[view.sort]); frame.showBtn:SetText("Show: " .. SHOWS[view.show])
  for k, b in pairs(frame.filters) do b:SetShown(cards); b:SetActive(cards and not view.showcase and k == view.kind) end
  frame.showcase:SetShown(cards); frame.showcase:SetActive(cards and view.showcase)
  for k, t in pairs(frame.modes) do t:SetActive(k == view.mode) end
  frame.prev:SetShown(cards); frame.next:SetShown(cards); frame.pageText:SetShown(cards)
  showRows(0)

  if cards then
    local list = collectionList(a)
    local pages = math.max(1, math.ceil(#list / #cells))
    view.page = math.max(1, math.min(view.page, pages))
    for i, cell in ipairs(cells) do
      local c = list[(view.page - 1) * #cells + i]
      paint(cell, c, c and bestFinish(a, c.id), c and owned(a, c.id))
    end
    frame.pageText:SetText(view.page .. " / " .. pages .. (view.set and ("  ·  " .. view.set) or ""))
    frame.prev:SetEnabled(view.page > 1); frame.next:SetEnabled(view.page < pages)
    if #list == 0 then frame.panel:ClearAllPoints(); frame.panel:SetPoint("TOPLEFT", 40, -260); frame.panel:SetText(view.showcase and "|cff9a96b0Your showcase is empty. Open a card you own and choose Showcase to pin it here.|r" or "|cff9a96b0Nothing matches. Change the search or the filters.|r") end
  elseif view.mode == "sets" then
    local sets = getSets()
    local per = 14
    local pages = math.max(1, math.ceil(#sets / per))
    local pg = math.max(0, math.min(view.setPage or 0, pages - 1)); view.setPage = pg
    local first = pg * per
    frame.panel:SetText("Complete a set to earn a coin reward. Click a set to browse it.   |cff9a96b0(" .. #sets .. " sets)|r")
    frame.panel:ClearAllPoints(); frame.panel:SetPoint("TOPLEFT", 40, -196)
    showRows(math.max(0, math.min(per, #sets - first)))
    for i = 1, per do
      local s = sets[first + i]
      local b = frame.rows[i]
      b:ClearAllPoints(); b:SetPoint("TOPLEFT", 40, -224 - (i - 1) * 29)
      if s then
        local have = setProgress(a, s)
        local done = have >= #s.cards
        b.left:SetText((done and "|cff7be08a" or "|cfff4ecd8") .. s.name .. "|r")
        b.right:SetText(have .. "/" .. #s.cards .. (done and ("   |cff7be08adone|r") or ("   +" .. s.reward)))
        b.act = function() view.set = s.name; view.mode = "cards"; view.kind = 0; view.page = 1; view.show = 1; RG.ArcadeRefresh(true) end
      end
    end
    frame.prev:Show(); frame.next:Show(); frame.pageText:Show()
    frame.pageText:SetText((pg + 1) .. " / " .. pages)
    frame.prev:SetEnabled(pg > 0); frame.next:SetEnabled(pg + 1 < pages)
  elseif view.mode == "today" then
    local g = todaysGoals(a)
    local lines = { GOLDHEX .. "Today|r", "" }
    lines[#lines + 1] = "Free packs waiting: |cffffffff" .. (a.free or 0) .. "|r   (one new pack every day, up to 3 saved)"
    lines[#lines + 1] = "Reward packs waiting: |cffffffff" .. (a.bonus or 0) .. "|r   (a new highest rank, and every 7th day in a row you break a pack)"
    lines[#lines + 1] = "Pack streak: |cffffffff" .. ((a.packDay == today() or a.packDay == yesterdayStr()) and (a.packStreak or 0) or 0) .. "|r day" .. "s in a row   ·   next pack's set: |cffffffff" .. (featuredSet(a) and featuredSet(a).name or "none") .. "|r"
    lines[#lines + 1] = "Pity: |cffffffff" .. (a.pity or 0) .. "|r of " .. PITY .. " packs without a holo or full art"
    lines[#lines + 1] = "Quest, kill and skill coins today: |cffffffff" .. ((a.day == today()) and (a.dayCoins or 0) or 0) .. "|r of " .. DAY_CAP
    lines[#lines + 1] = "Duel win streak: |cffffffff" .. (a.streak or 0) .. "|r   (each win in a row pays +1, up to +4)"
    lines[#lines + 1] = ""
    lines[#lines + 1] = GOLDHEX .. "Goals|r"
    for _, id in ipairs(g.pick) do
      for _, d in ipairs(GOALS) do
        if d[1] == id then
          local done = g.done[id]
          lines[#lines + 1] = (done and "|cff7be08a" or "|cfff4ecd8") .. d[2] .. "|r   " .. math.min(g.prog[id] or 0, d[3]) .. "/" .. d[3] .. "   ·   +" .. d[4] .. " coins" .. (done and "   done" or "")
        end
      end
    end
    frame.panel:ClearAllPoints(); frame.panel:SetPoint("TOPLEFT", 40, -204)
    frame.panel:SetText(table.concat(lines, "\n"))
  elseif view.mode == "trade" then
    local lines = { GOLDHEX .. "Trade with your party|r", "", "Offer an extra copy from its card (Offer to group). Someone in your group answers with one of their own extras and the swap happens when you both agree.", "Raiders can't be traded." }
    if trade.incoming then lines[#lines + 1] = ""; lines[#lines + 1] = "|cff7be08a" .. (trade.incoming.from or "Someone") .. " offers " .. trade.incoming.key .. " (" .. FNAME[trade.incoming.finish] .. ").|r Pick one of your extras below to answer." end
    if trade.out then lines[#lines + 1] = ""; lines[#lines + 1] = "Your offer: " .. trade.out.key .. " (" .. FNAME[trade.out.finish] .. "). Waiting for an answer." end
    if trade.pending then lines[#lines + 1] = ""; lines[#lines + 1] = "Answer sent. Waiting for " .. trade.pending.from .. "." end
    frame.panel:ClearAllPoints(); frame.panel:SetPoint("TOPLEFT", 40, -204)
    local ptext = table.concat(lines, "\n")
    frame.panel:SetText(ptext)
    local extras = {}
    for _, c in ipairs(CARDS) do
      if c.kind ~= 4 then
        local s = a.cards[c.key or c.name]
        if s then for f = 1, 4 do if (s[f] or 0) >= 2 then extras[#extras + 1] = { c = c, f = f, n = s[f] - 1 } end end end
      end
    end
    local n = math.min(8, #extras)
    showRows(n)
    for i = 1, n do
      local e = extras[i]
      local b = frame.rows[i]
      b:ClearAllPoints(); b:SetPoint("TOPLEFT", 40, -400 - (i - 1) * 29)
      b.left:SetText(e.c.name .. "  |cff9a96b0(" .. FNAME[e.f] .. ")|r"); b.right:SetText("x" .. e.n .. " extra")
      b.act = function()
        local ok, msg
        if trade.incoming then ok, msg = RG.ArcadeAcceptOffer(e.c, e.f) else ok, msg = RG.ArcadeOffer(e.c, e.f) end
        say(msg); RG.ArcadeRefresh(true)
      end
    end
    if #extras == 0 then frame.panel:SetText(ptext .. "\n\n|cff9a96b0You have no extra copies to trade yet.|r") end
  elseif view.mode == "stats" then
    local st = a.stats or {}
    local r = a.rarest
    local lines = { GOLDHEX .. "The Ledger|r", "",
      "Packs opened: |cffffffff" .. (a.packs or 0) .. "|r",
      "Rarest pull: |cffffffff" .. (r and (r.name .. " (" .. FNAME[r.finish] .. ")") or "none yet") .. "|r",
      "Duels: |cffffffff" .. (a.wins or 0) .. " won, " .. (a.losses or 0) .. " lost|r",
      "", GOLDHEX .. "Coins earned|r",
      string.format("XP %d  ·  level-ups %d  ·  quests %d  ·  kills %d", st.xp or 0, st.level or 0, st.quest or 0, st.kill or 0),
      string.format("Skill-ups %d  ·  duels %d  ·  goals %d  ·  sets %d", st.skill or 0, st.duel or 0, st.goal or 0, st.sets or 0),
      "", "Characters met: |cffffffff" .. (function() local n = 0; for _ in pairs(a.raiders or {}) do n = n + 1 end return n end)() .. "|r",
    }
    frame.panel:ClearAllPoints(); frame.panel:SetPoint("TOPLEFT", 40, -204)
    frame.panel:SetText(table.concat(lines, "\n"))
  end
  local free = a.free or 0
  local bonus = a.bonus or 0
  if bonus > 0 then frame.buy:SetText("Break a reward pack  (" .. bonus .. ")")
  else frame.buy:SetText(free > 0 and ("Break a free pack  (" .. free .. ")") or (PACK_PRICE == 0 and "Open a pack  ·  free" or ("Break a pack  ·  " .. PACK_PRICE))) end
  frame.buy:SetEnabled(afford() and true or false)
  local ready = RG.ArcadeSealsReady and RG.ArcadeSealsReady() or 0
  if ready >= 2 then frame.buyAll:SetText("Break all  (" .. ready .. ")"); frame.buyAll:Show() else frame.buyAll:Hide() end
end

RG.ArcadeUI = { layoutText = layoutText, makeCard = makeCard, paint = paint, fs = fs, setfont = setfont, fitText = fitText, gbtn = gbtn, gtab = gtab, darkPanel = darkPanel, lv = lv,
  MEDIA = MEDIA, GOLDC = GOLDC, TIER = TIER, FINISH = FINISH, KINDCOL = KINDCOL, CARDS = CARDS, byKey = byKey, store = store, bestFinish = bestFinish,
  owned = owned, iconFor = iconFor, usesScene = usesScene, newScene = newScene, setScene = setScene, hideScene = hideScene, goalProgress = goalProgress, FONT = FONT, WHITE = WHITE }

RG.ArcadePackPrice = PACK_PRICE
-- the Cards tab opens a pack straight away
function RG.ArcadeBuyNow(many)
  RG.ShowArcade()
  if frame and frame.buyNow then frame.buyNow(many) end
end
function RG.ShowArcade()
  if WaypathFrame and WaypathFrame.IsShown and WaypathFrame:IsShown() then WaypathFrame:Hide() end   -- never stack on the main window
  if not frame then build() end
  local a = store(); if a then a.seen = true end
  frame:Show(); RG.ArcadeRefresh()
end

local base = SlashCmdList.WAYPATH
SlashCmdList.WAYPATH = function(msg)
  local cmd = (msg or ""):match("^%s*(%S+)")
  cmd = cmd and cmd:lower()
  if cmd == "arcade" or cmd == "cards" then RG.ShowArcade() return end
  return base(msg)
end
